contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(to == address(0), "need zero-address recipient");

        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(to);
        uint256 supplyAfter = c.totalSupply();

        assert(reverted
            && balSenderAfter == balSenderBefore
            && balRecipientAfter == balRecipientBefore
            && supplyAfter == supplyBefore);
    }

    receive() external payable {}
}

